import sys

def main():
    data = sys.stdin.read().split()
    if not data:
        return
    n = int(data[0])
    arr = []
    idx = 1
    while len(arr) < n and idx < len(data):
        arr.append(int(data[idx]))
        idx += 1

    MOD = 1000000007
    arr.sort()
    max_val = 100000
    dp = [0] * (max_val + 1)

    for x in arr:
        dp[x] = 1

    for x in arr:
        for i in range(1, int(x**0.5) + 1):
            if x % i == 0:
                j = x // i
                if i in dp and j in dp:
                    ways_left = dp[i]
                    ways_right = dp[j]
                    if i == j:
                        term = (ways_left * ways_right) % MOD
                    else:
                        term = (2 * ways_left * ways_right) % MOD
                    dp[x] = (dp[x] + term) % MOD

    total = sum(dp[x] for x in arr) % MOD
    print(total)

if __name__ == "__main__":
    main()
